/// <summary>Simple in-memory notebook for the agent's research notes.</summary>
sealed class Notebook
{
    private readonly List<(string Label, string Content)> _notes = [];

    public int Count => _notes.Count;

    public void Save(string label, string content) =>
        _notes.Add((label, content));

    public string GetAll()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n\n---\n\n",
            _notes.Select((n, i) => $"**Note {i + 1} – {n.Label}**\n{n.Content}"));
    }
}

/// <summary>Lightweight web search using DuckDuckGo Lite (no API key required).</summary>
static class WebSearch
{
    private static readonly HttpClient Http = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
        },
        Timeout = TimeSpan.FromSeconds(15),
    };

    public static async Task<string> SearchAsync(string query)
    {
        try
        {
            var url = $"https://lite.duckduckgo.com/lite/?q={Uri.EscapeDataString(query)}";
            var html = await Http.GetStringAsync(url);
            return ParseResults(html, query);
        }
        catch (Exception ex)
        {
            return $"Search failed ({ex.GetType().Name}): {ex.Message}. " +
                   "Try rephrasing the query.";
        }
    }

    private static string ParseResults(string html, string query)
    {
        // DuckDuckGo Lite returns a simple HTML page with result links and snippets.
        var results = new List<string>();
        var spans = html.Split("<a rel=\"nofollow\"", StringSplitOptions.RemoveEmptyEntries);

        for (var i = 1; i < spans.Length && results.Count < 6; i++)
        {
            var span = spans[i];
            var hrefStart = span.IndexOf("href=\"", StringComparison.Ordinal);
            if (hrefStart < 0) continue;
            hrefStart += 6;
            var hrefEnd = span.IndexOf('"', hrefStart);
            if (hrefEnd < 0) continue;

            var link = span[hrefStart..hrefEnd];
            if (link.StartsWith('/')) continue; // skip internal links

            // Extract the visible title text
            var titleEnd = span.IndexOf("</a>", StringComparison.Ordinal);
            var titleStart = span.IndexOf('>', hrefEnd) + 1;
            var title = titleStart > 0 && titleEnd > titleStart
                ? StripTags(span[titleStart..titleEnd]).Trim()
                : link;

            // Extract snippet (next <td> with class "result-snippet")
            var snippetMarker = span.IndexOf("result-snippet", StringComparison.Ordinal);
            var snippet = "";
            if (snippetMarker >= 0)
            {
                var sStart = span.IndexOf('>', snippetMarker) + 1;
                var sEnd = span.IndexOf("</td>", sStart, StringComparison.Ordinal);
                if (sStart > 0 && sEnd > sStart)
                    snippet = StripTags(span[sStart..sEnd]).Trim();
            }

            results.Add($"{results.Count + 1}. {title}\n   URL: {link}" +
                         (snippet.Length > 0 ? $"\n   {snippet}" : ""));
        }

        return results.Count > 0
            ? $"Search results for '{query}':\n\n{string.Join("\n\n", results)}"
            : $"No results found for '{query}'. Try a different query.";
    }

    private static string StripTags(string html)
    {
        var inTag = false;
        var chars = new char[html.Length];
        var ci = 0;
        foreach (var c in html)
        {
            if (c == '<') { inTag = true; continue; }
            if (c == '>') { inTag = false; continue; }
            if (!inTag) chars[ci++] = c;
        }
        return new string(chars, 0, ci)
            .Replace("&amp;", "&")
            .Replace("&lt;", "<")
            .Replace("&gt;", ">")
            .Replace("&quot;", "\"")
            .Replace("&#x27;", "'");
    }
}

